#!/usr/bin/env node
/**
 * Builds the website's pages (home.html, features.html, download.html, faq.html, privacy.html,
 * changelog.html, contact.html at the repo root) from web/pages/*.html bodies with one shared
 * <head>, header and footer. Run it after editing a page:  node scripts/build-site.mjs
 * The generated files are committed; Vite builds them like any other page.
 */
import { readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { join, resolve } from 'node:path';

const ROOT = resolve(import.meta.dirname, '..');
const PAGES = join(ROOT, 'web', 'pages');

const NAV = [
  ['/features', 'Features'],
  ['/download', 'Download'],
  ['/faq', 'FAQ'],
  ['/changelog', 'What’s new'],
  ['/contact', 'Contact'],
];

const page = ({ file, path, title, description, script, body }) => `<!doctype html>
<html lang="en">
  <head>
    <!-- Generated by scripts/build-site.mjs from web/pages/${file}. Edit that, then run the script. -->
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover" />
    <title>${title}</title>
    <meta name="description" content="${description}" />
    <meta name="theme-color" content="#08080f" />
    <meta name="apple-mobile-web-app-capable" content="yes" />
    <meta name="mobile-web-app-capable" content="yes" />
    <meta name="apple-mobile-web-app-title" content="Aether" />
    <meta name="apple-mobile-web-app-status-bar-style" content="default" />
    <meta property="og:title" content="${title}" />
    <meta property="og:description" content="${description}" />
    <meta property="og:image" content="/site/layout-orbit.webp" />
    <link rel="icon" href="/icon.svg" type="image/svg+xml" />
    <link rel="manifest" href="/manifest.webmanifest" />
  </head>
  <body>
    <a class="skip" href="#main">Skip to content</a>
    <header class="nav">
      <a class="brand" href="/"><img src="/icon.svg" alt="" width="28" height="28" /> Aether</a>
      <nav class="links" aria-label="Site">
${NAV.map(([href, label]) => `        <a href="${href}"${href === path ? ' aria-current="page"' : ''}>${label}</a>`).join('\n')}
      </nav>
      <div class="auth" id="auth">
        <a class="btn ghost" href="/app?auth=signin">Log in</a>
        <a class="btn primary" href="/app?auth=signup">Sign up</a>
      </div>
    </header>

    <main id="main">
${body.trimEnd()}
    </main>

    <footer class="foot">
      <span><img src="/icon.svg" alt="" width="18" height="18" /> Aether · free, no ads</span>
      <nav aria-label="Footer">
        <a href="/app">Web app</a> · <a href="/download">Download</a> · <a href="/faq">FAQ</a> · <a href="/privacy">Privacy</a> · <a href="/changelog">What’s new</a> · <a href="/contact">Contact us</a>
      </nav>
    </footer>

    <script type="module" src="/src/home/${script}"></script>
  </body>
</html>
`;

for (const file of readdirSync(PAGES).filter((f) => f.endsWith('.html'))) {
  const raw = readFileSync(join(PAGES, file), 'utf8');
  // Front matter: <!-- key: value --> lines at the top.
  const meta = Object.fromEntries([...raw.matchAll(/^<!-- (\w+): (.*?) -->$/gm)].map((m) => [m[1], m[2]]));
  const body = raw.replace(/^<!-- \w+: .*? -->\r?\n/gm, '');
  const name = file.replace(/\.html$/, '');
  const out = name === 'home' ? 'home.html' : `${name}.html`;
  writeFileSync(join(ROOT, out), page({ file, path: name === 'home' ? '/' : `/${name}`, title: meta.title, description: meta.description, script: meta.script ?? 'main.ts', body }));
  console.log('wrote', out);
}
